const m2Norm = (s) => String(s ?? "").toUpperCase().replace(/[^A-Z0-9]/g, "");
const m2Serial = (n) => new Date(Math.round((n - 25569) * 86400000)).toISOString().slice(0, 10);
function m2Date(s) {
  s = String(s).trim(); if (m2ISO(s)) return s;
  let m = s.match(/^(\d{1,2})[/.-](\d{1,2})[/.-](\d{4})$/); if (m) return `${m[3]}-${m[1].padStart(2, "0")}-${m[2].padStart(2, "0")}`;
  m = s.match(/^([A-Za-z]{3,9})\.? (\d{1,2}),? (\d{4})$/); if (m) { const d = new Date(`${m[1]} ${m[2]}, ${m[3]} 12:00`); if (!isNaN(d)) return PAY.iso(d); }
  return null;
}
async function m2Read(file) {
  let X; try { X = await loadLib("xlsx"); } catch { toast("Couldn't load the Excel tools. Check your connection and try again."); return null; }
  const wb = X.read(await file.arrayBuffer(), { type: "array" });
  const names = wb.SheetNames.slice().sort((a, b) => (/201/.test(b) ? 1 : 0) - (/201/.test(a) ? 1 : 0));
  for (const sn of names) { const aoa = X.utils.sheet_to_json(wb.Sheets[sn], { header: 1, raw: true, defval: null, blankrows: true });
    for (let h = 0; h < Math.min(aoa.length, 30); h++) { const n = (aoa[h] || []).map(m2Norm); if (n.includes("IDNUMBER") && n.includes("EMPLOYEEFULLNAME")) return { sheet: sn, aoa, h }; } }
  return null;
}
function m2Cols(hdr) {
  const n = hdr.map(m2Norm); const seen = {}; const map = {};
  for (const [c, k, label] of M2) { const L = m2Norm(label); const occ = (seen[L] = (seen[L] || 0) + 1);
    if (n[c] === L) { map[k] = c; continue; } let found = -1, cnt = 0; for (let i = 0; i < n.length; i++) if (n[i] === L && ++cnt === occ) { found = i; break; } map[k] = found; }
  return map;
}
