  for (const x of items) { const dn = M2_DEPT_ALIAS[m2Norm(x.deptName)] || x.deptName; if (dn && !D.has(m2Norm(dn))) nd.add(m2Title(dn)); if (x.posTitle && !P.has(m2Norm(x.posTitle))) np.add(m2Norm(x.posTitle)); if (x.proj && !C.has(m2Norm(x.proj))) nc.add(x.proj); }
