const M2_DEPT_ALIAS = { FINANCEANDACCOUNTING: "Accounting", HUMANRESOURCES: "Human Resources", IT: "Information Technology" };

/* ---------- import dialog ---------- */
let m2Got = null;
function m2Modal() {
  m2Got = null;
  openModal(modalHead("Import 201 masterlist", "The GPPMC Employee 201 File Masterlist in Excel. People are matched by ID number: existing ones are updated, new ones are added.") +
    dropZone("m2-file", ".xlsx,.xls,.xlsm", "Drop the masterlist here") + '<div id="m2-prev" aria-live="polite" style="margin-top:14px"></div>', "m201");
}
async function m2Preview(file) {
  const box = $("#m2-prev"); if (!box) return; box.innerHTML = '<p class="t-muted">Reading the file…</p>';
  let got = null; try { got = await m2Read(file); } catch {} if (!got) { box.innerHTML = '<p class="err">This file doesn\'t look like the 201 masterlist. It needs a header row with ID NUMBER and EMPLOYEE FULL NAME.</p>'; return; }
  m2Got = m2Plan(got); m2Draw();
}
function m2Draw() {
  const box = $("#m2-prev"); if (!box || !m2Got) return; const { items, skipped, sheet, mapped } = m2Got; const scope = S.m2Scope || (window.__hosted ? "all" : "active");
  const use = items.filter((x) => scope === "all" || x.active); const add = use.filter((x) => !x.prev).length; const act = items.filter((x) => x.active).length;
  const o = m2Orgs(use); const after = S.emps.size + add; const tooMany = !window.__hosted && after > 1000;
  box.innerHTML = `<p style="margin:0;font-weight:600">Sheet "${esc(sheet)}": ${items.length} people (${act} active, ${items.length - act} inactive). ${mapped} of ${M2.length} columns matched.</p>
    <div style="display:flex;gap:16px;flex-wrap:wrap;margin:10px 0"><label class="check" style="padding:0"><input type="radio" name="m2-scope" value="active" ${scope === "active" ? "checked" : ""}><span>Active employees only (${act})</span></label>
      <label class="check" style="padding:0"><input type="radio" name="m2-scope" value="all" ${scope === "all" ? "checked" : ""}><span>Everyone, with inactive people as separated (${items.length})</span></label></div>
    <ul style="margin:0;padding-left:18px;font-size:14px"><li>${add} new 201 files, ${use.length - add} updated</li>
      ${o.nc.length ? `<li>${o.nc.length} project codes will be added: ${esc(o.nc.slice(0, 12).join(", "))}${o.nc.length > 12 ? "…" : ""}. Give them their full names in Projects afterwards.</li>` : ""}
      ${o.nd.length ? `<li>${o.nd.length} departments will be added: ${esc(o.nd.join(", "))}</li>` : ""}${o.np ? `<li>${o.np} job titles will be added to Positions</li>` : ""}
      <li>Pay amounts aren't in the masterlist, so basic pay stays as it is (new people start at ₱0 until Pay setup is filled in).</li></ul>
    ${skipped.length ? `<details style="margin-top:8px"><summary class="t-muted" style="cursor:pointer">${skipped.length} rows will be skipped</summary><ul class="err" style="margin:6px 0 0;padding-left:18px">${skipped.slice(0, 30).map((p) => `<li>${esc(p)}</li>`).join("")}${skipped.length > 30 ? `<li>…and ${skipped.length - 30} more</li>` : ""}</ul></details>` : ""}
    <div class="table-wrap" style="margin-top:10px"><table><thead><tr><th>ID no.</th><th>Name</th><th>Job title</th><th>Project</th><th>Status</th></tr></thead><tbody>${use.slice(0, 5).map((x) => `<tr><td>${esc(x.no)}</td><td>${esc(`${x.core.first} ${x.core.last}`)}</td><td>${esc(x.posTitle)}</td><td>${esc(x.proj || "HO")}</td><td>${x.active ? esc(STATUS[x.core.status]?.[0] || "") : `Separated · ${esc(x.core.separated.reason)}`}</td></tr>`).join("")}</tbody></table></div>
    ${tooMany ? `<p class="err" style="margin-top:10px">This version of the app holds up to 1,000 employees. Choose Active employees only here, or import everyone on the website.</p>` : ""}
    <div style="display:flex;gap:12px;align-items:center;margin-top:12px"><button class="btn btn-primary" data-m2-go="1" ${tooMany || !use.length ? "disabled" : ""}>Import ${use.length} people</button><span id="m2-progress" class="t-muted"></span></div>`;
}
async function m2Run() {
  if (!m2Got || !S.canEdit) return; const scope = S.m2Scope || (window.__hosted ? "all" : "active"); const use = m2Got.items.filter((x) => scope === "all" || x.active); if (!use.length) return;
  const btn = $("[data-m2-go]"); if (btn) btn.disabled = true; const prog = $("#m2-progress");
  const org = JSON.parse(JSON.stringify(S.org)); let orgChanged = false;
  const codes = new Set(org.departments.map((d) => d.code));
  const findDept = (name) => { if (!name) return null; const n = m2Norm(M2_DEPT_ALIAS[m2Norm(name)] || name); let d = org.departments.find((x) => m2Norm(x.name) === n || m2Norm(x.code) === n);
    if (!d) { const nm = m2Title(M2_DEPT_ALIAS[m2Norm(name)] || name); let c = nm.replace(/[^A-Za-z]/g, "").slice(0, 3).toUpperCase() || "DEP"; for (let i = 2; codes.has(c); i++) c = c.slice(0, 3) + i; codes.add(c); d = { id: uid(), code: c, name: nm }; org.departments.push(d); orgChanged = true; } return d.id; };
  const findPos = (title, deptId) => { if (!title) return null; const n = m2Norm(title); let p = org.positions.find((x) => m2Norm(x.title) === n && x.deptId === deptId) || org.positions.find((x) => m2Norm(x.title) === n);
    if (!p) { p = { id: uid(), title: m2Title(title), deptId }; org.positions.push(p); orgChanged = true; } return p.id; };
  const projBy = new Map([...S.projects.values()].map((p) => [m2Norm(p.code), p])); const newProj = [];
  for (const x of use) if (x.proj && !projBy.has(m2Norm(x.proj))) { const p = { id: uid(), req: {}, code: x.proj, name: x.proj, client: null, location: null, status: "ACTIVE", managerId: null, start: null, end: null, region: null, description: "Added from the 201 masterlist" }; projBy.set(m2Norm(x.proj), p); newProj.push(p); }
  try {
    const plan = use.map((x) => { const deptId = findDept(x.deptName); const posId = findPos(x.posTitle, deptId); const pj = x.proj ? projBy.get(m2Norm(x.proj)) : null; const pv = x.prev;
      const keep = Object.fromEntries(Object.entries(x.core).filter(([k, v]) => v != null && v !== "" || k === "separated"));
      const e = pv ? { ...pv, ...keep, deptId: deptId || pv.deptId, posId: posId || pv.posId, projectId: x.proj ? pj.id : null, projectSince: x.proj ? (pv.projectId === pj.id ? pv.projectSince : pv.projectSince || x.core.hire) : null }
        : { id: uid(), suffix: null, title: null, photo: null, supervisorId: null, payType: "MONTHLY", basicPay: 0, shiftId: "day", docs: [], ...x.core, deptId, posId, projectId: pj?.id || null, projectRole: pj ? m2Title(x.posTitle || "") || null : null, projectSince: pj ? x.core.hire : null, projectUntil: null,
            history: [{ d: x.core.hire, kind: "Hired", text: `Hired as ${m2Title(x.posTitle || "employee")}` }].concat(x.core.separated ? [{ d: x.core.separated.date, kind: "Separated", text: x.core.separated.reason }] : []) };
      if (x.bankAcct) { e.bankAcct = x.bankAcct; if (x.bank) e.bank = x.bank; }
      if (pv && !pv.separated && x.core.separated) e.history = [...(pv.history || []), { d: x.core.separated.date, kind: "Separated", text: x.core.separated.reason }];
      return [e, x.m]; });
    if (orgChanged) { await S.db.doc("org/main").set(org); S.org = org; }
    for (const p of newProj) { const { id, ...body } = p; await S.db.doc("projects/" + id).set(body); S.projects.set(id, p); }
    let done = 0;
    for (let i = 0; i < plan.length; i += 8) {
      await Promise.all(plan.slice(i, i + 8).map(async ([e, m]) => { await saveEmp(e); S.emps.set(e.id, e);
        if (Object.keys(m).length) { const ref = S.db.doc(`m201/${e.id}`); try { await ref.update(m); } catch { await ref.set(m); } S.m2.set(e.id, { ...(S.m2.get(e.id) || {}), ...m }); } }));
      done = Math.min(plan.length, i + 8); if (prog) prog.textContent = `${done} of ${plan.length} saved…`;
    }
    const added = use.filter((x) => !x.prev).length;
    logActivity(`Imported the 201 masterlist: ${added} added, ${use.length - added} updated`); toast(`201 masterlist imported: ${added} added, ${use.length - added} updated.`);
    m2Got = null; closeModal(); S.ver++; go("employees");
  } catch { if (btn) btn.disabled = false; if (prog) prog.textContent = ""; toast("Some records couldn't be saved. Check your connection and import again; finished rows are simply updated."); }
}

/* ---------- download in the masterlist layout ---------- */
async function m2Export() {
  let X; try { X = await loadLib("xlsx"); } catch { toast("Couldn't load the Excel tools. Check your connection and try again."); return; }
  toast("Preparing the masterlist…"); const all = new Map();
  try { const s = await S.db.collection("m201").limit(window.__hosted ? 5000 : 1000).get(); for (const d of s.docs) all.set(d.id, d.data()); } catch {}
  const W = 310; const blank = () => Array(W).fill(null);
  const r1 = blank(); r1[0] = "GPPMC EMPLOYEE 201 FILE MASTERLIST"; const r2 = blank(); r2[0] = `As of ${fmtDate(todayISO())}`; const r4 = blank(); const r5 = blank();
  for (const [c, l] of Object.entries(M2_GROUPS)) r4[c] = l; for (const [c, , label] of M2) r5[c] = label;
  const emps = [...S.emps.values()].filter((e) => !e.sample).sort((a, b) => (a.separated ? 1 : 0) - (b.separated ? 1 : 0) || String(a.no).localeCompare(String(b.no), undefined, { numeric: true }));
  const rows = emps.map((e) => { const m = { ...(S.m2.get(e.id) || {}), ...(all.get(e.id) || {}) }; const r = blank();
    for (const [c, k, , , t, core] of M2) { let v = core ? m2Core(e, k) : m[k]; if (v == null || v === "") continue; 
      r[c] = m2ISO(v) && (t === "d" || k === "hire" || k === "birth") ? new Date(`${v}T00:00:00`) : v; }
    return r; });
  const ws = X.utils.aoa_to_sheet([r1, r2, blank(), r4, r5, ...rows], { cellDates: true, dateNF: "mm/dd/yyyy" }); ws["!cols"] = Array.from({ length: W }, (_, c) => ({ wch: c === 8 ? 30 : 16 }));
  const wb = X.utils.book_new(); X.utils.book_append_sheet(wb, ws, "Employee 201 File Masterlist");
  await saveBlob(`GPPMC Employee 201 Masterlist ${todayISO()}.xlsx`, new Blob([X.write(wb, { bookType: "xlsx", type: "array" })], { type: XLSX_TYPE }));
  logActivity(`Downloaded the 201 masterlist (${rows.length} people)`);
}

/* The general Import dialog hands the masterlist to this importer. */
{ const b = previewFile; previewFile = async (file) => { if (/\.xls[xm]?$/i.test(file?.name || "") && S.canEdit) { let got = null; try { got = await m2Read(file); } catch {} if (got) { m2Modal(); m2Got = m2Plan(got); m2Draw(); return; } } return b(file); }; }

document.addEventListener("click", async (ev) => {
  const t = ev.target.closest("[data-full201],[data-m2-edit],[data-m2-cancel],[data-m2-jump],[data-m2-imp],[data-m2-exp],[data-m2-go]"); if (!t) return; const d = t.dataset;
  if (d.full201) { S.m2Edit = null; go("f201", { id: d.full201 }); return; }
  if (d.m2Edit) { S.m2Edit = { id: S.view.id, sec: d.m2Edit }; render(); setTimeout(() => document.querySelector(".m2-form input:not([disabled]), .m2-form textarea")?.focus(), 30); return; }
  if (d.m2Cancel) { S.m2Edit = null; render(); return; }
  if (d.m2Jump) { document.getElementById(d.m2Jump)?.scrollIntoView({ behavior: "smooth", block: "start" }); return; }
  if (d.m2Imp) return m2Modal();
  if (d.m2Exp) return m2Export();
  if (d.m2Go) return m2Run();
});
document.addEventListener("change", (ev) => { const t = ev.target;
  if (t.id === "m2-file" && t.files?.[0]) return m2Preview(t.files[0]);
  if (t.name === "m2-scope") { S.m2Scope = t.value; m2Draw(); } });
document.addEventListener("drop", (ev) => { const z = ev.target.closest?.("#m2-file-drop"); if (!z) return; ev.preventDefault(); z.classList.remove("drag"); const f = ev.dataTransfer?.files?.[0]; if (f) m2Preview(f); }, true);
document.addEventListener("submit", async (ev) => {
  const f = ev.target.closest?.(".m2-form"); if (!f) return; ev.preventDefault(); ev.stopImmediatePropagation(); const e = S.emps.get(S.view.id); if (!e || !S.canEdit) return;
  const sec = f.dataset.sec; const next = { ...(S.m2.get(e.id) || {}) };
  for (const [, k, , s, , core] of M2) { if (s !== sec || core || !f.elements[k]) continue; const v = f.elements[k].value.trim(); if (v) next[k] = v; else delete next[k]; }
  const btn = f.querySelector("button.btn-primary"); if (btn) btn.disabled = true;
  try { await S.db.doc(`m201/${e.id}`).set(JSON.parse(JSON.stringify(next))); S.m2.set(e.id, next); S.m2Edit = null; logActivity(`Updated ${sec} in ${fullName(e)}'s 201 file`); toast("Saved."); render(); }
  catch { if (btn) btn.disabled = false; toast("Couldn't save. Check your connection and try again."); }
}, true);
